/**
 * The figure asset (`figure.glb`): a skinned, sculpted body mesh generated by
 * `scripts/figure/generate-figure.ts` from MakeHuman's CC0 assets.
 *
 * Besides the standard glTF skin data, every vertex carries:
 * - `_MUSCLE_GROUPS` / `_MUSCLE_COVER`: up to four muscle groups (index into
 *   `MUSCLES`, 255 = none) and how much of the vertex each covers (0–1).
 * - `_CAVITY`: baked cavity shading (1 = open, lower in creases).
 *
 * The skeleton is the animation rig (`rig.ts`) plus bones the animation format
 * never sets: finger and toe bones (hand shapes, toe bend) and blend bones
 * that soften the bends at shoulders, elbows, hips, knees and forearms.
 */
import { MUSCLES, type Muscle } from '../schema/common.ts';
import { JOINT_NAMES, SIDES, type JointName, type Side } from './rig.ts';

export const FINGERS = ['thumb', 'index', 'middle', 'ring', 'pinky'] as const;
export type Finger = (typeof FINGERS)[number];

/** Finger bone name, e.g. `leftIndex2` (1 = nearest the wrist). */
export function fingerBone(side: Side, finger: Finger, segment: 1 | 2 | 3): string {
  return `${side}${finger[0]?.toUpperCase()}${finger.slice(1)}${segment}`;
}

export function toesBone(side: Side): string {
  return `${side}Toes`;
}

/**
 * A blend bone is driven by two joints of the rig:
 * - "blend": pivots at the `child` joint, turned half-way between the
 *   `parent`'s and the `child`'s rotation (softens the bend).
 * - "twist": pivots at the `parent` joint, turned like the `parent` plus half
 *   of the `child`'s twist about the parent bone (forearm twist as the hand
 *   turns).
 * - "swing": pivots at the `child` joint, turned like the `child` but with
 *   only a quarter of its twist about its own bone (the top of the upper arm
 *   and the shoulder cap do not spin with the arm).
 * Its bind pose is at its pivot, unrotated.
 */
export interface BlendBone {
  name: string;
  kind: 'blend' | 'twist' | 'swing';
  parent: JointName;
  child: JointName;
}

export const BLEND_BONES: readonly BlendBone[] = SIDES.flatMap((side): BlendBone[] => [
  { name: `${side}ShoulderBlend`, kind: 'blend', parent: 'chest', child: `${side}Shoulder` },
  { name: `${side}UpperArmTwist`, kind: 'swing', parent: 'chest', child: `${side}Shoulder` },
  { name: `${side}ElbowBlend`, kind: 'blend', parent: `${side}Shoulder`, child: `${side}Elbow` },
  { name: `${side}ForearmTwist`, kind: 'twist', parent: `${side}Elbow`, child: `${side}Wrist` },
  { name: `${side}HipBlend`, kind: 'blend', parent: 'pelvis', child: `${side}Hip` },
  { name: `${side}KneeBlend`, kind: 'blend', parent: `${side}Hip`, child: `${side}Knee` },
]);

export interface FigureBoneSpec {
  name: string;
  /** Parent bone, or null for a root (the pelvis and the blend bones). */
  parent: string | null;
}

/** Every bone of the figure's skeleton, parents before children. */
export const FIGURE_BONES: readonly FigureBoneSpec[] = (() => {
  const parents: Record<JointName, JointName | null> = {
    pelvis: null,
    spine: 'pelvis',
    chest: 'spine',
    neck: 'chest',
    head: 'neck',
    leftShoulder: 'chest',
    leftElbow: 'leftShoulder',
    leftWrist: 'leftElbow',
    rightShoulder: 'chest',
    rightElbow: 'rightShoulder',
    rightWrist: 'rightElbow',
    leftHip: 'pelvis',
    leftKnee: 'leftHip',
    leftAnkle: 'leftKnee',
    rightHip: 'pelvis',
    rightKnee: 'rightHip',
    rightAnkle: 'rightKnee',
  };
  const bones: FigureBoneSpec[] = JOINT_NAMES.map((name) => ({ name, parent: parents[name] }));
  for (const side of SIDES) {
    for (const finger of FINGERS) {
      bones.push({ name: fingerBone(side, finger, 1), parent: `${side}Wrist` });
      bones.push({ name: fingerBone(side, finger, 2), parent: fingerBone(side, finger, 1) });
      bones.push({ name: fingerBone(side, finger, 3), parent: fingerBone(side, finger, 2) });
    }
    bones.push({ name: toesBone(side), parent: `${side}Ankle` });
  }
  for (const blend of BLEND_BONES) bones.push({ name: blend.name, parent: null });
  return bones;
})();

/** Index of each bone in `FIGURE_BONES` (also the skin joint index). */
export const FIGURE_BONE_INDEX: ReadonlyMap<string, number> = new Map(
  FIGURE_BONES.map((bone, index) => [bone.name, index]),
);

/** Glow index of each muscle group (position in `MUSCLES`). */
export function muscleIndex(muscle: Muscle): number {
  return MUSCLES.indexOf(muscle);
}

/** Marks an unused muscle slot. */
export const NO_MUSCLE = 255;

export interface FigureBoneData {
  name: string;
  parent: string | null;
  /** Bind-pose transform relative to the parent (or the world for roots). */
  position: [number, number, number];
  quaternion: [number, number, number, number];
}

export interface FigureAsset {
  vertexCount: number;
  positions: Float32Array;
  indices: Uint16Array | Uint32Array;
  /** Four skin joints per vertex (indices into `bones`). */
  skinIndex: Uint8Array;
  /** Four skin weights per vertex, 0–255 (normalised). */
  skinWeight: Uint8Array;
  /** Four muscle group indices per vertex (`NO_MUSCLE` when unused). */
  muscleGroups: Uint8Array;
  /** Coverage of each of the four groups, 0–255. */
  muscleCover: Uint8Array;
  /** Cavity shading per vertex, 0–255. */
  cavity: Uint8Array;
  bones: FigureBoneData[];
  /** Column-major 4×4 inverse bind matrix of each bone. */
  inverseBindMatrices: Float32Array;
}

/** The file is not a figure asset this app can read. */
export class FigureAssetFormatError extends Error {
  override name = 'FigureAssetFormatError';
}

function formatError(message: string): FigureAssetFormatError {
  console.error(message);
  return new FigureAssetFormatError(message);
}

interface GltfAccessor {
  bufferView: number;
  byteOffset?: number;
  componentType: number;
  count: number;
  type: string;
}

interface GltfJson {
  accessors: GltfAccessor[];
  bufferViews: { byteOffset?: number; byteLength: number; byteStride?: number }[];
  meshes: { primitives: { attributes: Record<string, number>; indices: number }[] }[];
  nodes: {
    name?: string;
    children?: number[];
    translation?: number[];
    rotation?: number[];
    mesh?: number;
    skin?: number;
  }[];
  skins: { joints: number[]; inverseBindMatrices: number }[];
}

const GLB_MAGIC = 0x46546c67;
const CHUNK_JSON = 0x4e4f534a;
const CHUNK_BIN = 0x004e4942;
const COMPONENT_ARRAYS: Record<
  number,
  Uint8ArrayConstructor | Uint16ArrayConstructor | Uint32ArrayConstructor | Float32ArrayConstructor
> = {
  5121: Uint8Array,
  5123: Uint16Array,
  5125: Uint32Array,
  5126: Float32Array,
};
const TYPE_SIZES: Record<string, number> = { SCALAR: 1, VEC3: 3, VEC4: 4, MAT4: 16 };

/**
 * Reads the figure asset from a binary glTF (`.glb`) file.
 *
 * @throws {FigureAssetFormatError} when the file is not a figure asset.
 */
export function parseFigureAsset(buffer: ArrayBuffer): FigureAsset {
  const view = new DataView(buffer);
  if (buffer.byteLength < 20 || view.getUint32(0, true) !== GLB_MAGIC) {
    throw formatError('The figure asset is not a binary glTF file');
  }
  let json: GltfJson | null = null;
  let bin: Uint8Array | null = null;
  let offset = 12;
  while (offset + 8 <= buffer.byteLength) {
    const length = view.getUint32(offset, true);
    const type = view.getUint32(offset + 4, true);
    const data = new Uint8Array(buffer, offset + 8, length);
    if (type === CHUNK_JSON) json = JSON.parse(new TextDecoder().decode(data)) as GltfJson;
    else if (type === CHUNK_BIN) bin = data;
    offset += 8 + length;
  }
  if (!json || !bin) throw formatError('The figure asset lacks its JSON or binary chunk');
  const gltf = json;
  const body = bin;
  const file = body.buffer as ArrayBuffer;

  const accessor = (index: number | undefined) => {
    const spec = index === undefined ? undefined : gltf.accessors[index];
    const bufferView = spec ? gltf.bufferViews[spec.bufferView] : undefined;
    const ArrayType = spec ? COMPONENT_ARRAYS[spec.componentType] : undefined;
    const size = spec ? TYPE_SIZES[spec.type] : undefined;
    if (!spec || !bufferView || !ArrayType || !size) {
      throw formatError(`The figure asset has a missing or unsupported accessor ${index}`);
    }
    const start = body.byteOffset + (bufferView.byteOffset ?? 0) + (spec.byteOffset ?? 0);
    const elementBytes = size * ArrayType.BYTES_PER_ELEMENT;
    const stride = bufferView.byteStride ?? elementBytes;
    if (stride === elementBytes) {
      // Copy so the arrays are aligned and independent of the file buffer.
      return new ArrayType(file.slice(start, start + spec.count * elementBytes));
    }
    const source = new Uint8Array(file);
    const bytes = new Uint8Array(spec.count * elementBytes);
    for (let i = 0; i < spec.count; i++) {
      const from = start + i * stride;
      bytes.set(source.subarray(from, from + elementBytes), i * elementBytes);
    }
    return new ArrayType(bytes.buffer);
  };

  const primitive = gltf.meshes[0]?.primitives[0];
  const skin = gltf.skins[0];
  if (!primitive || !skin) throw formatError('The figure asset has no skinned mesh');
  const attribute = (name: string) => accessor(primitive.attributes[name]);
  const positions = attribute('POSITION');
  const indices = accessor(primitive.indices);
  const parts = {
    skinIndex: attribute('JOINTS_0'),
    skinWeight: attribute('WEIGHTS_0'),
    muscleGroups: attribute('_MUSCLE_GROUPS'),
    muscleCover: attribute('_MUSCLE_COVER'),
    cavity: attribute('_CAVITY'),
  };
  for (const [name, array] of Object.entries(parts)) {
    if (!(array instanceof Uint8Array)) throw formatError(`${name} must be unsigned bytes`);
  }
  if (!(positions instanceof Float32Array)) throw formatError('POSITION must be float');
  if (!(indices instanceof Uint16Array || indices instanceof Uint32Array)) {
    throw formatError('Indices must be 16 or 32 bit');
  }
  const inverseBindMatrices = accessor(skin.inverseBindMatrices);
  if (!(inverseBindMatrices instanceof Float32Array)) {
    throw formatError('Inverse bind matrices must be float');
  }

  const parentOf = new Map<number, number>();
  gltf.nodes.forEach((node, index) => {
    for (const child of node.children ?? []) parentOf.set(child, index);
  });
  const bones: FigureBoneData[] = skin.joints.map((nodeIndex) => {
    const node = gltf.nodes[nodeIndex];
    const parent = parentOf.get(nodeIndex);
    const [x = 0, y = 0, z = 0] = node?.translation ?? [];
    const [qx = 0, qy = 0, qz = 0, qw = 1] = node?.rotation ?? [];
    return {
      name: node?.name ?? '',
      parent: parent === undefined ? null : (gltf.nodes[parent]?.name ?? null),
      position: [x, y, z],
      quaternion: [qx, qy, qz, qw],
    };
  });
  const expected = FIGURE_BONES.map((bone) => `${bone.name}<${bone.parent ?? ''}`).join(',');
  const actual = bones.map((bone) => `${bone.name}<${bone.parent ?? ''}`).join(',');
  if (expected !== actual) throw formatError('The figure asset skeleton does not match the app');

  return {
    vertexCount: positions.length / 3,
    positions,
    indices,
    skinIndex: parts.skinIndex as Uint8Array,
    skinWeight: parts.skinWeight as Uint8Array,
    muscleGroups: parts.muscleGroups as Uint8Array,
    muscleCover: parts.muscleCover as Uint8Array,
    cavity: parts.cavity as Uint8Array,
    bones,
    inverseBindMatrices,
  };
}
